import heapq

def main():
    N, M = map(int, input().split())
    edge = [[] for _ in range(N)]
    for _ in range(M):
        l, d, k, c, A, B = map(int, input().split())
        A -= 1
        B -= 1
        edge[A].append((l, d, k, c, B))

    P = [(-10**20, i) for i in range(N-1)]
    heapq.heapify(P)
    ans = [-10**20] * N

    while P:
        time, pos = heapq.heappop(P)
        time *= -1
        if ans[pos] > time:
            continue
        ans[pos] = time
        for l, d, k, c, B in edge[pos]:
            t = time - c
            kt = (t - l) // d
            if kt < 0:
                continue
            if kt > k - 1:
                kt = k - 1
            new_time = l + kt * d + c
            if ans[B] < new_time:
                heapq.heappush(P, (-new_time, B))

    for a in ans[:N-1]:
        print(a if a > -10**20 else '-∞')
